// Effect kinds interpreted by spells.cpp. Fields a,b,c are documented per kind there.
enum EffKind : u8 {
  E_NONE = 0,
  // passive stats
  E_MAXHP, E_MAXHP_PCT, E_MOVE_PCT, E_ATKSPD_PCT, E_CD_PCT, E_CRIT, E_CRITDMG, E_FLATDMG, E_DMG_PCT, E_RES,
  E_TAKEN_PCT, E_RANGED_TAKEN_PCT, E_DEBUFF_PCT, E_LIFESTEAL, E_KILLHEAL, E_REGEN, E_REFLECT, E_DODGE, E_THROWSPD_PCT,
  E_RANGE_PCT, E_HEAL_PCT, E_DEALT_PCT, E_LOWHP_DMG, E_VS_SLOWED, E_VS_BURNING, E_VS_WOUNDED, E_VS_FROZEN, E_CRITBONUS,
  E_IMMUNE_SLOW, E_HP_PER_WAVE, E_LIGHTNING_PCT, E_ALLNUM_PCT, E_CHAINPLUS, E_SHIELD_WAVE, E_BLOCK_WAVE, E_REVIVE,
  E_MIRROR, E_ATTACKER_DMG, E_BURN_TOUCH, E_WARMTH, E_ARMOR_IGNORE, E_DRONE_MINIGUN, E_SENTINEL,
  // projectile mods
  E_PIERCE, E_BOUNCE_ENEMY, E_BOUNCE_WALL, E_HOMING, E_SPLIT, E_EXPLODE, E_KNOCKBACK, E_ORBIT, E_WHIRL,
  // on hit
  E_HIT_SLOW, E_HIT_FREEZE, E_HIT_STUN, E_HIT_ROOT, E_HIT_BURN, E_HIT_BLEED, E_HIT_CHAIN, E_HIT_BONUS, E_HIT_BURST,
  E_HIT_BOLT, E_CRIT_CHAIN, E_CRIT_BURN, E_CRIT_HEAL, E_EXSANG, E_MARK,
  // on kill
  E_KILL_BURST, E_KILL_POISON, E_KILL_CLOUD, E_KILL_SLOWAOE, E_KILL_CHAIN, E_KILL_MOVE, E_KILL_MAXHP, E_KILL_CURSE,
  E_KILL_EXPLODE_BURNING, E_KILL_HEALEVERY,
  // every Nth throw / periodic
  E_NTH_RING, E_NTH_BLAST, E_NTH_STUN, E_NTH_DOUBLE, E_NTH_STRIKE3, E_NTH_BOLT, E_PERIODIC_FLARE, E_PERIODIC_BOMB,
  // auras / trails
  E_AURA, E_AURA_PULL, E_AURA_WEAKEN, E_AURA_MISS, E_AURA_HEALKILL, E_TRAIL_FIRE, E_TRAIL_SPARK,
  E_COUNT
};
struct Eff { u8 kind; float a, b, c; };
struct SpellDef { u8 el, ty, act, rar, sc, season; Eff eff[3]; };
struct SpellText { const char* name; const char* desc; const char* stats; };
extern const int SPELL_COUNT;
extern const SpellDef SPELLS[NUM_SPELLS];
extern const SpellText* const SPELL_TEXT[LANG_COUNT];
extern const char* const* const SPELL_LORE[LANG_COUNT];

